#!/usr/bin/env python3
from pathlib import Path
import subprocess,sys
root=Path(sys.argv[1]); touched=set()
def edit(path,old,new,count=1):
 p=root/path;s=p.read_text();assert s.count(old)==count,(path,old[:100],s.count(old));p.write_text(s.replace(old,new));touched.add(path)
p='internal/qualitygate/coordinator.go'
edit(p,'candidateErr == nil && len(candidates) > 0 {','candidateErr == nil && len(candidates) > 0 && candidates[len(candidates)-1].Attempt >= tx.Attempt {')
p='internal/server/qualityruntime/runtime.go'
edit(p,'Arcs must be within target_chapter; choose POV from characters.','Arcs must be ordered, contiguous from chapter 1 through target_chapter with no gaps or overlap; choose POV from characters. The complete response must remain within 48 KiB.')
edit(p,'Use a stable POV id from foundation.characters; do not grant knowledge of unknown secrets.','Use exactly planning_pov, the POV whose knowledge was used to select the context; do not switch POV or grant knowledge of unknown secrets.')
edit(p,'Do not plan beyond target_chapter. Return one strict JSON object without fences matching: " + string(schema), "architect", nil','Do not plan beyond target_chapter. batch_target_chapter is only an execution stop, not the ending of the book. Return one strict JSON object without fences matching: " + string(schema), "planner", nil')
p='web/src/pages/Autopilot.test.ts'
edit(p,"id: 'job_test', project_id:","id: 'job_test', revision: 7, review_candidate_id: 'candidate_1', project_id:")
edit(p,"{ job, candidate_text: 'A reviewed chapter.'","{ job, candidate_id: 'candidate_1', candidate_text: 'A reviewed chapter.'")
edit(p,"  await fireEvent.click(screen.getByText('查看候选与计划'));","  expect((screen.getByText('批准本章并继续') as HTMLButtonElement).disabled).toBe(true);\n  await fireEvent.click(screen.getByText('查看候选与计划'));")
edit(p,"  expect(new Headers(write.init?.headers).get('Idempotency-Key')).toBeTruthy();","  expect(new Headers(write.init?.headers).get('Idempotency-Key')).toBeTruthy();\n  expect(JSON.parse(String(write.init?.body))).toEqual({ expected_revision: 7, review_candidate_id: 'candidate_1' });")
# Direct legacy wizard callers still receive explicit nonblank selections.
# Run the pre-existing wizard tests rather than replacing their assertions.
p='docs/AUTOPILOT.md'
with (root/p).open('a') as f:f.write('''\n\n## Phase 9 closure — 2026-09-05\n\nPR #37 was merged at `1a96ab344a8d337af38da51bc080810a63d0a72d`. A conversation summary incorrectly said it was not delivered; repository history, not that summary, is the baseline. This follow-up closes specific orchestration gaps, without restarting Phase 10–13.\n\n- STOP cannot be downgraded by a later PAUSE. Replayed no-op commands do not append new events or invalidate a displayed review revision. Each worker claim has a persisted generation, so an old attempt cannot checkpoint a new attempt. A step that returns no progress fails rather than spinning.\n- REVIEW_REQUIRED resume needs `expected_revision` and `review_candidate_id` from the inspected detail response. Empty/stale approvals return 409. The UI requires inspecting the current revision before approval. Normal resume still accepts an empty object.\n- Interrupted rewrites reconstruct the same previous draft, feedback and attempt. Persisted model results replay without changing the request identity or consuming a second rewrite slot.\n- A finite batch does not shorten the novel's Foundation horizon. Book horizon is snapshotted independently. Foundations are size-bounded, validated on reuse and must have contiguous arc coverage. A saved Foundation that cannot cover an expanded book target stops with `FOUNDATION_HORIZON_MISMATCH`; create a new Foundation request rather than silently rewriting the existing plan.\n- Planner uses its configured `planner` role and exactly the selected `planning_pov`. A different POV is rejected before Writer. Progress defaults come from contiguous completed version/saga/checkpoint proofs, not legacy summary counts.\n- An opaque fingerprint of authoritative event positions and prior Finals binds the chapter plan. Changed accepted facts, Ledger or prior Finals stop old work with `CHAPTER_CONTEXT_CHANGED`. Fingerprints intentionally invalidate conservatively even for unrelated later authority edits; they are not story content. A migrated in-flight task lacking a baseline stops with `CONTEXT_BASELINE_REQUIRED`, not an invented current snapshot.\n- Resolve a stale chapter through the existing explicit human version Check/Accept/Finalize path, then resume: a proved completed Human Final takes over the chapter without replacement by the older draft. An incomplete generated Final saga is replayed first with its original key. The system does not pretend that an old plan was automatically replanned or that an Active Final pointer proves commit completion.\n- Project writes recheck the task under the project OS lock; archive/delete uses the live-slot query instead of a history page. Worker lock symlinks are rejected. No old migration is edited.\n\nVerification remains named state/control, replay, short chapter flows, contract and UI checks plus entry and asset builds. Exact results and merge SHA are recorded in the closure PR. No full Go/Vitest/race suites, paid model calls, 300-chapter simulation or platform/scale matrix is claimed. Phase 9 is a bounded functional delivery; those explicitly deferred acceptance scopes remain unexecuted.\n''')
touched.add(p)
p='docs/ROADMAP.md'
with (root/p).open('a') as f:f.write('\n### Phase 9 closure scope\n\nPhase 9 production implementation was merged in PR #37; orchestration follow-up and recovery limits are documented in [AUTOPILOT.md](AUTOPILOT.md). Phase 10–13 remain paused. Historical 300-chapter and full-suite acceptance are still deferred by the limited-check policy, not reported as passed.\n')
touched.add(p)
for p in touched:
 if p.endswith('.go'):subprocess.run(['gofmt','-w',str(root/p)],check=True)
subprocess.run(['git','add','--']+sorted(touched),cwd=root,check=True)
subprocess.run(['git','diff','--cached','--check'],cwd=root,check=True)
